INSERT INTO `hero_chat` VALUES (3,'Halo! ???? Ingin kenalan singkat dengan saya?','Hi! Want a quick introduction about me?','Salam kenal! Nama Saya Radhitya Sofwan Rahmat, Saya lahir di Jakarta dan sekarang berusia 25 tahun.','Nice to meet you! My name is Radhitya Sofwan Rahmat. I was born in Jakarta and I am now 25 years old.','text',0),(4,'Mau tahu bagaimana saya memulai karir di Digital Marketing?','Want to know how I started my career in Digital Marketing?','Saya memulainya dari nol sebagai admin e-commerce. Saya belajar banyak hal hingga akhirnya membangun dan mengelola online shop sendiri secara mandiri.','I started from zero as an e-commerce admin. I learned many things until I was able to build and manage my own online shop independently.','text',2),(5,'Penasaran dengan pencapaian terbesar yang pernah saya raih?','Curious about the biggest milestone I have achieved?','Di 2024, saya tembus 1.000 order/bulan untuk produk skincare dengan margin 50rb/pcs','In 2024, I reached 1,000 orders per month for skincare products with a margin of around Rp50,000 per item.','text',3),(6,'Mau Info sejak kapan saya berkarir di Digital Marketing ?','Want to know when I started my career in Digital Marketing?','Perjalanan karir saya mulai terbentuk sejak kuliah semester 4 di tahun 2021.','My career journey started taking shape in 2021, during my fourth semester in college.','text',1),(7,'Sekalian kasih tahu pencapaian di tahun 2025 ?','Let me also share one milestone from 2025.','2025, saya berhasil menggandakan (2x lipat) basis pelanggan aplikasi kasir.','In 2025, I managed to double the customer base of a point-of-sale app.','cta',4);
/*!40000 ALTER TABLE `hero_chat` ENABLE KEYS */;
