INSERT INTO `profile` VALUES (1,'Radhitya Sofwan Rahmat','Digital Marketer dan Growth Engineer berbasis data dengan fokus pada Paid Ads (Meta Ads dan Google Ads), SEO, copywriting, content strategy, serta social media management. Menggabungkan optimasi funnel dan landing page CRO dengan pengembangan web app dan SaaS (PWA) berbasis AI untuk automasi campaign, tracking, dan dashboard analitik agar eksekusi growth lebih cepat, efisien, dan terukur.','Data-driven Digital Marketer and Growth Engineer focused on Paid Ads (Meta Ads and Google Ads), SEO, copywriting, content strategy, and social media management. I combine funnel optimization and landing page CRO with AI-powered web app and SaaS (PWA) development for campaign automation, tracking, and analytics dashboards so growth execution becomes faster, more efficient, and more measurable.','','6281288844813','radhityasofwan27@gmail.com','DICH','DICH','Digital Marketer & Growth Engineer','Digital Marketer & Growth Engineer','uploads/1767188884_hero.png','uploads/1767188884_photo.jpg','OPEN FOR PROJECTS','OPEN FOR PROJECTS',1,'uploads/1767188884_cv.pdf','','A curated selection of campaigns, websites, and product builds with a strong focus on measurable growth, clearer messaging, and faster execution.','','If you need help with paid ads, SEO, landing pages, automation, or product experimentation, I would be happy to discuss the right direction for your business.',12,'Digital Marketer Jakarta, Web Developer Jakarta, Meta Ads, Google Ads, SEO Specialist, Social Media Manager, Landing Page, WordPress, PHP MySQL, SaaS, PWA','Digital Marketer Jakarta, Web Developer Jakarta, Meta Ads, Google Ads, SEO Specialist, Social Media Manager, Landing Page, WordPress, PHP MySQL, SaaS, PWA','','https://www.linkedin.com/in/radhityasofwan27?utm_source=share&utm_campaign=share_via&utm_content=profile&utm_medium=android_app','https://www.instagram.com/radhityasfwn?igsh=MWU2ZzV5YnR5MXNrbA==','https://www.facebook.com/share/19xWaaDLjY/','','https://www.tiktok.com/@ruangdigitalan?_r=1&_t=ZS-92fpoHU0Bk4','https://www.threads.com/@radhityasfwn','https://x.com/radhityasof','https://pastidigital.com/','\n\n','','','');
